'use strict';
// Mock iDRAC (Redfish), Proxmox, TrueNAS (JSON-RPC over WebSocket) and a UniFi OS console on one
// self-signed HTTPS server (127.0.0.1:18443).
const https = require('node:https');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

// Self-signed test certificate, generated by test/run.js
const certDir = process.env.MOCK_CERT_DIR || __dirname;
const opts = { key: fs.readFileSync(path.join(certDir, 'key.pem')), cert: fs.readFileSync(path.join(certDir, 'cert.pem')) };
let requests = 0;
let unifiLogins = 0;
const seenAuth = [];

const R = (o) => JSON.stringify(o);
const redfish = {
  '/redfish/v1/Systems': { Members: [{ '@odata.id': '/redfish/v1/Systems/System.Embedded.1' }] },
  '/redfish/v1/Systems/System.Embedded.1': {
    Model: 'PowerEdge R730xd', SKU: 'ABC1234', HostName: 'pve1', PowerState: 'On', Status: { Health: 'OK', State: 'Enabled' },
    Links: { Chassis: [{ '@odata.id': '/redfish/v1/Chassis/System.Embedded.1' }] },
  },
  '/redfish/v1/Chassis/System.Embedded.1/Power': {
    PowerControl: [{ PowerConsumedWatts: 212 + Math.round(Math.random() * 20) }],
    PowerSupplies: [
      { Name: 'PS1 Status', Status: { Health: 'OK', State: 'Enabled' }, PowerInputWatts: 110, PowerCapacityWatts: 750, LineInputVoltage: 232 },
      { Name: 'PS2 Status', Status: { Health: 'Critical', State: 'Enabled' }, PowerInputWatts: 0, PowerCapacityWatts: 750, LineInputVoltage: 0 },
    ],
  },
  '/redfish/v1/Chassis/System.Embedded.1/Thermal': {
    Temperatures: [
      { Name: 'System Board Inlet Temp', ReadingCelsius: 22, UpperThresholdNonCritical: 42, UpperThresholdCritical: 47, Status: { Health: 'OK' } },
      { Name: 'CPU1 Temp', ReadingCelsius: 54, UpperThresholdNonCritical: 85, UpperThresholdCritical: 90, Status: { Health: 'OK' } },
      { Name: 'CPU2 Temp', ReadingCelsius: 88, UpperThresholdNonCritical: 85, UpperThresholdCritical: 90, Status: { Health: 'Warning' } },
    ],
    Fans: [1, 2, 3, 4, 5, 6].map((i) => ({ Name: `System Board Fan${i}`, Reading: i === 6 ? 0 : 3000 + i * 1500, ReadingUnits: 'RPM', Status: { Health: i === 6 ? 'Critical' : 'OK' } })),
  },
};

function wsAccept(key) {
  return crypto.createHash('sha1').update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
}
function wsSend(sock, text) {
  const p = Buffer.from(text);
  let h;
  if (p.length < 126) h = Buffer.from([0x81, p.length]);
  else if (p.length < 65536) { h = Buffer.alloc(4); h[0] = 0x81; h[1] = 126; h.writeUInt16BE(p.length, 2); }
  else { h = Buffer.alloc(10); h[0] = 0x81; h[1] = 127; h.writeBigUInt64BE(BigInt(p.length), 2); }
  sock.write(Buffer.concat([h, p]));
}

const server = https.createServer(opts, (req, res) => {
  requests++;
  const u = req.url;
  if (u === '/__stats') { res.end(R({ requests, seenAuth, unifiLogins })); return; }
  seenAuth.push(req.headers.authorization || null);
  if (u.startsWith('/redfish/')) {
    if (req.headers.authorization !== 'Basic ' + Buffer.from('root:calvin').toString('base64')) { res.writeHead(401); return res.end('{}'); }
    const body = redfish[u];
    if (!body) { res.writeHead(404); return res.end('{}'); }
    res.setHeader('Content-Type', 'application/json');
    return res.end(R(body));
  }
  if (u === '/api/auth/login' && req.method === 'POST') {
    let body = '';
    req.on('data', (c) => (body += c));
    req.on('end', () => {
      unifiLogins++;
      let j = {};
      try { j = JSON.parse(body); } catch {}
      if (j.username === 'viewer' && j.password === 'unifipass') {
        res.writeHead(200, { 'Set-Cookie': ['TOKEN=mocktoken-SECRETJWT; path=/; secure; httponly; samesite=strict'], 'X-CSRF-Token': 'csrf123', 'Content-Type': 'application/json' });
        return res.end(R({ username: 'viewer' }));
      }
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(R({ code: 'AUTHENTICATION_FAILED_INVALID_CREDENTIALS' }));
    });
    return;
  }
  if (u.startsWith('/proxy/network/')) {
    if (!/TOKEN=mocktoken-SECRETJWT/.test(req.headers.cookie || '')) { res.writeHead(401); return res.end(R({ meta: { rc: 'error', msg: 'api.err.LoginRequired' } })); }
    if (u === '/proxy/network/api/self/sites') return res.end(R({ meta: { rc: 'ok' }, data: [{ name: 'default', desc: 'Default' }] }));
    if (u === '/proxy/network/api/s/default/rest/networkconf') return res.end(R({ meta: { rc: 'ok' }, data: [
      { name: 'Internet 1', purpose: 'wan', x_pppoe_password: 'PPPOE-SECRET-PW', wan_type: 'pppoe' },
      { name: 'LAN', purpose: 'corporate', ip_subnet: '192.168.1.1/24', vlan_enabled: false, dhcpd_enabled: true, dhcpd_start: '192.168.1.100', dhcpd_stop: '192.168.1.250', domain_name: 'home.example.com' },
      { name: 'Mgmt', purpose: 'corporate', ip_subnet: '192.168.2.1/24', vlan_enabled: true, vlan: 10, dhcpd_enabled: false },
      { name: 'Site VPN', purpose: 'site-vpn', ip_subnet: '192.168.50.1/24', x_ipsec_pre_shared_key: 'IPSEC-SECRET-PSK' },
    ] }));
    if (u === '/proxy/network/api/s/default/stat/sta') return res.end(R({ meta: { rc: 'ok' }, data: [
      { mac: 'aa:bb:cc:00:00:01', hostname: 'orion', ip: '127.0.0.1', is_wired: true, sw_mac: 'f4:e2:c6:aa:bb:cc', sw_port: 7, network: 'LAN', use_fixedip: true, fixed_ip: '192.168.1.80' },
      { mac: 'aa:bb:cc:00:00:02', name: 'Printer', ip: '192.168.1.120', is_wired: true, sw_mac: 'f4:e2:c6:aa:bb:cc', sw_port: 8, network: 'LAN' },
      { mac: 'aa:bb:cc:00:00:03', hostname: 'phone', ip: '192.168.1.131', is_wired: false, ap_mac: '24:5a:4c:11:22:33', network: 'LAN' },
    ] }));
    if (u === '/proxy/network/api/s/default/stat/health') return res.end(R({ meta: { rc: 'ok' }, data: [
      { subsystem: 'wlan', num_user: 14, num_ap: 1, status: 'ok' },
      { subsystem: 'wan', status: 'ok', wan_ip: '203.0.113.45' },
      { subsystem: 'www', status: 'ok', latency: 7, xput_down: 912.4, xput_up: 487.1 },
      { subsystem: 'lan', num_user: 23, num_sw: 1, status: 'ok' },
    ] }));
    if (u === '/proxy/network/api/s/default/stat/device') {
      const sw = Array.from({ length: 26 }, (_, i) => ({
        port_idx: i + 1, name: i === 2 ? 'U7 Pro' : `Port ${i + 1}`, up: [0, 1, 2, 4, 7, 24].includes(i), speed: i === 24 ? 10000 : 1000,
        media: i >= 24 ? 'SFP+' : 'GE', is_uplink: i === 24, port_poe: i < 16, poe_enable: i < 16, poe_power: i === 2 ? '9.84' : i === 4 ? '4.21' : '0.00',
      }));
      const udm = Array.from({ length: 11 }, (_, i) => ({ port_idx: i + 1, name: i === 8 ? 'WAN' : `Port ${i + 1}`, up: [0, 8, 9].includes(i), speed: 1000, media: i >= 9 ? 'SFP+' : 'GE', is_uplink: i === 8 }));
      return res.end(R({ meta: { rc: 'ok' }, data: [
        { mac: '24:5A:4C:11:22:33', name: 'U7 Pro Hallway', model: 'U7PRO', type: 'uap', state: 1, version: '8.0.19', uptime: 86400, 'system-stats': { cpu: '4.1', mem: '38.2' }, num_sta: 14, radio_table_stats: [{ radio: 'ng', channel: 6, num_sta: 3, satisfaction: 98 }, { radio: 'na', channel: 36, num_sta: 9 }, { radio: '6e', channel: 37, num_sta: 2 }], uplink: { uplink_mac: 'f4:e2:c6:aa:bb:cc', uplink_remote_port: 3 } },
        { mac: 'f4:e2:c6:aa:bb:cc', name: 'USW-24-POE Rack', model: 'USL24P', type: 'usw', state: 1, version: '7.1.26', uptime: 1209600, 'system-stats': { cpu: '9.0', mem: '41.0' }, general_temperature: 46, fan_level: 0, total_max_power: 95, port_table: sw, num_sta: 23 },
        { mac: '74:ac:b9:dd:ee:ff', name: 'UDM Pro', model: 'UDMPRO', type: 'udm', state: 1, version: '4.1.13', upgradable: true, uptime: 2592000, 'system-stats': { cpu: '18.5', mem: '72.3' }, temperatures: [{ name: 'CPU', type: 'cpu', value: 61.2 }, { name: 'Local', type: 'board', value: 48.0 }, { name: 'PHY', type: 'phy', value: 57.5 }], fan_level: 30, port_table: udm, num_sta: 37 },
      ] }));
    }
  }
  if (u.startsWith('/api2/json/')) {
    if (req.headers.authorization !== 'PVEAPIToken=root@pam!dash=11111111-2222-3333-4444-555555555555') { res.writeHead(401); return res.end('{}'); }
    if (u === '/api2/json/nodes') return res.end(R({ data: [
      { node: 'pve1', status: 'online', cpu: 0.12, maxcpu: 32, mem: 40e9, maxmem: 128e9, disk: 20e9, maxdisk: 100e9, uptime: 864000 },
      { node: 'pve2', status: 'offline' },
    ] }));
    if (u === '/api2/json/cluster/resources?type=vm') return res.end(R({ data: [
      { vmid: 100, name: 'truenas', type: 'qemu', status: 'running', node: 'pve1', cpu: 0.05, maxcpu: 8, mem: 32e9, maxmem: 34e9, uptime: 86400 },
      { vmid: 101, name: 'docker', type: 'lxc', status: 'running', node: 'pve1', cpu: 0.2, maxcpu: 4, mem: 2e9, maxmem: 4e9, uptime: 3600 },
      { vmid: 102, name: 'win11', type: 'qemu', status: 'stopped', node: 'pve1', maxmem: 8e9 },
      { vmid: 9000, name: 'tmpl', type: 'qemu', status: 'stopped', node: 'pve1', template: 1 },
    ] }));
  }
  res.writeHead(404);
  res.end('{}');
});

server.on('upgrade', (req, sock) => {
  requests++;
  if (req.url !== '/api/current') { sock.end('HTTP/1.1 404 Not Found\r\n\r\n'); return; }
  sock.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${wsAccept(req.headers['sec-websocket-key'])}\r\n\r\n`);
  let buf = Buffer.alloc(0);
  let authed = false;
  sock.on('data', (d) => {
    buf = Buffer.concat([buf, d]);
    while (buf.length >= 2) {
      let len = buf[1] & 0x7f, off = 2;
      if (len === 126) { len = buf.readUInt16BE(2); off = 4; } else if (len === 127) { len = Number(buf.readBigUInt64BE(2)); off = 10; }
      if (!(buf[1] & 0x80)) { sock.destroy(); return; } // client frames must be masked
      const mask = buf.subarray(off, off + 4); off += 4;
      if (buf.length < off + len) return;
      const op = buf[0] & 0x0f;
      const p = Buffer.from(buf.subarray(off, off + len)); for (let i = 0; i < p.length; i++) p[i] ^= mask[i & 3];
      buf = buf.subarray(off + len);
      if (op === 0x8) { sock.end(); return; }
      handle(JSON.parse(p.toString()));
    }
  });
  function handle(msg) {
  {
    {
      seenAuth.push(msg.method);
      const reply = (result) => wsSend(sock, R({ jsonrpc: '2.0', id: msg.id, result }));
      const err = (code, message) => wsSend(sock, R({ jsonrpc: '2.0', id: msg.id, error: { code, message } }));
      // a notification interleaved, like real middleware
      wsSend(sock, R({ jsonrpc: '2.0', method: 'collection_update', params: {} }));
      if (msg.method === 'auth.login_ex') {
        authed = msg.params[0].username === 'truenas_admin' && msg.params[0].api_key === '1-abcdefKEY';
        return reply({ response_type: authed ? 'SUCCESS' : 'AUTH_ERR' });
      }
      if (!authed) return err(-32001, 'Not authenticated');
      if (msg.method === 'system.info') return reply({ hostname: 'nas', version: 'TrueNAS-26.04.0', system_product: 'Mock NAS', model: 'Xeon', cores: 16, physmem: 68719476736, uptime_seconds: 123456, loadavg: [0.5, 0.4, 0.3] });
      if (msg.method === 'pool.query') return reply([
        { name: 'tank', status: 'ONLINE', healthy: true, warning: false, size: 40e12, allocated: 30e12, free: 10e12 },
        { name: 'fast', status: 'DEGRADED', healthy: false, warning: true, size: 2e12, allocated: 0.5e12, free: 1.5e12, status_detail: 'One or more devices faulted' },
      ]);
      if (msg.method === 'alert.list') return reply([
        { level: 'WARNING', formatted: 'Pool fast state is DEGRADED', dismissed: false, datetime: { $date: Date.now() - 60000 } },
        { level: 'INFO', formatted: 'old', dismissed: true, datetime: { $date: Date.now() } },
        { level: 'CRITICAL', formatted: 'x'.repeat(70000), dismissed: false, datetime: { $date: Date.now() - 120000 } },
      ]);
      err(-32601, 'Method not found');
    }
  }
  }
});

server.listen(18443, '127.0.0.1', () => console.log('mock on 18443'));
